definition.script:
node {
    currentBuild.displayName = "#${env.BUILD_NUMBER} ${params.RUN_ID}"
    currentBuild.description = "app=${params.APP_CODE} branch=${params.BRANCH} commit=${params.COMMIT_ID}"

    stage('Checkout') {
        def remote = [url: params.REPO_URL]
        if (params.GIT_CREDENTIALS_ID?.trim()) {
            remote.credentialsId = params.GIT_CREDENTIALS_ID
        }
        checkout([$class: 'GitSCM',
            branches: [[name: params.BRANCH]],
            userRemoteConfigs: [remote]
        ])
        if (params.COMMIT_ID?.trim()) {
            withEnv(["FERRY_COMMIT=${params.COMMIT_ID}"]) {
                if (isUnix()) {
                    sh 'git checkout --force "$FERRY_COMMIT"'
                } else {
                    bat 'git checkout --force "%FERRY_COMMIT%"'
                }
            }
        }
    }

    def specText = params.STAGE_SPEC?.trim()
    def stageSpec = []
    if (specText) {
        try {
            stageSpec = readJSON(text: specText)
        } catch (MissingMethodException ignored) {
            stageSpec = new groovy.json.JsonSlurperClassic().parseText(specText)
        }
    }
    for (s in stageSpec) {
        stage(s.name) {
            timeout(time: s.timeoutSeconds ?: 1800, unit: 'SECONDS') {
                echo "Ferry 阶段 ${s.name}，构建工具 ${s.buildTool ?: '未配置'}"
                for (t in s.tasks ?: []) {
                    if (t.scriptContent?.trim()) {
                        if (isUnix()) {
                            sh t.scriptContent
                        } else {
                            bat t.scriptContent
                        }
                    } else if (t.scriptRef?.trim()) {
                        echo "任务 ${t.name} 未填写执行命令，仅配置 scriptRef=${t.scriptRef}"
                    } else {
                        echo "任务 ${t.name} 未配置脚本，跳过"
                    }
                }
                if (s.type == 4) {
                    for (p in s.outputs ?: []) {
                        archiveArtifacts artifacts: p, allowEmptyArchive: true, fingerprint: true
                    }
                }
            }
        }
    }
}
